PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;

ALTER TABLE note RENAME TO note_old;

CREATE TABLE "note" (
    "id" INTEGER NOT NULL,
    "id_gruppo" INTEGER,
    "nome" VARCHAR NOT NULL,
    "price_delta_euro" NUMERIC(8, 2),
    PRIMARY KEY("id"),
    FOREIGN KEY("id_gruppo") REFERENCES "note_gruppi"("id")
);

SELECT "id", "id_gruppo", "nome", "price_delta_euro"
FROM "note_old";

DROP TABLE "note_old";

COMMIT;
PRAGMA foreign_keys = ON;







